theorem complementFaceReturn (S : CyclicStaircase) {b : Point3}
    (hb : MinimalComplement S.D b) (i : Fin 3) (hbi : 0 < b.coord i) :
    (S.rho b).coord i = 0

theorem return_ne_of_support_inter (S : CyclicStaircase) {b c : Point3}
    (hb : MinimalComplement S.D b) (hc : MinimalComplement S.D c)
    (hbc : b ≠ c) (hi : SupportInter b c) : S.rho b ≠ S.rho c

theorem fullSupport_minimalComplement_atMostOne (S : CyclicStaircase) {b c : Point3}
    (hb : MinimalComplement S.D b) (hc : MinimalComplement S.D c)
    (hfb : FullSupport b) (hfc : FullSupport c) : b = c

theorem fullSupport_puncturedCore_mem (S : CyclicStaircase) {g p : Point3}
    (hg : MinimalComplement S.D g) (hfull : FullSupport g)
    (hp : FullBoundaryPuncturedCore S g p) : p ∈ S.D

theorem pair12_terminal_return_capacity (S : CyclicStaircase) {g : Point3}
    (hg : MinimalComplement S.D g) (hfull : FullSupport g) :
    pair12Count S.D ≤ g.x + g.y + g.z - 2

theorem pair12_face_axis_pressure (S : CyclicStaircase) {A B : ℕ}
    (hm : Point3.mk A B 0 ∈ S.D) :
    pair12Count S.D+A+B ≤ (pure1Intercept S-1)+(pure2Intercept S-1)

theorem fullSupport_symbolic_BF_lower (S : CyclicStaircase) {g : Point3}
    (hg : MinimalComplement S.D g) (hf : FullSupport g) (ho : PairCountsOrdered S) :
    fullSupportSymbolicBF S g ≤ S.m

theorem fullSupport_tGE4_ordered_symbolic_sharp (S : CyclicStaircase) {g : Point3}
    (hg : MinimalComplement S.D g) (hf : FullSupport g) (ho : PairCountsOrdered S)
    (ht : 4 ≤ pair23Count S.D) : fullTarget S ≤ S.m

theorem evenIndex_injective (L k : ℕ) (hk : 0 < k) {p q : Point3}
    (hp : EvenRegion L k p) (hq : EvenRegion L k q)
    (he : evenIndex k p = evenIndex k q) : p=q

theorem evenIndex_bounds (L k : ℕ) (hL : k < L) {p : Point3}
    (hp : EvenRegion L k p) :
    -(L : ℤ) < evenIndex k p ∧ evenIndex k p ≤ (k : ℤ)*k+k

theorem oddIndex_bounds (L k : ℕ) (hk : 0 < k) (hL : k ≤ L) {p : Point3}
    (hp : OddRegion L k p) :
    -(L : ℤ) ≤ evenIndex k p ∧ evenIndex k p ≤ (k : ℤ)*k

theorem symbolic_H_positive_box_lower (S : CyclicStaircase) {g : Point3}
    (hfull : FullSupport g) :
    g.x * g.y * g.z - 1 ≤ (fullSupportSymbolicH S g).card

theorem fullSupport_t1_ordered_symbolic_sharp (S : CyclicStaircase) {g : Point3}
    (hg : MinimalComplement S.D g) (hf : FullSupport g) (ho : PairCountsOrdered S)
    (ht : pair23Count S.D=1) : fullTarget S ≤ S.m

theorem fullSupport_t2_ordered_symbolic_sharp (S : CyclicStaircase) {g : Point3}
    (hg : MinimalComplement S.D g) (hf : FullSupport g)
    (ho : PairCountsOrdered S) (ht : pair23Count S.D=2) : fullTarget S≤S.m

theorem t3_unit_z_capacity (S : CyclicStaircase) {g : Point3}
    (hg : MinimalComplement S.D g) (hf : FullSupport g) (ho : PairCountsOrdered S)
    (hz : g.z = 1) : pair12Count S.D + 1 ≤ g.x + g.y

theorem t3_unit_y_capacity (S : CyclicStaircase) {g : Point3}
    (hg : MinimalComplement S.D g) (hf : FullSupport g) (ho : PairCountsOrdered S)
    (hy : g.y = 1) : pair12Count S.D + 1 ≤ g.x + g.z

theorem t3_unit_x_capacity (S : CyclicStaircase) {g : Point3}
    (hg : MinimalComplement S.D g) (hf : FullSupport g) (ho : PairCountsOrdered S)
    (hx : g.x=1) : pair12Count S.D+1 ≤ g.y+g.z

theorem thin23_lifted_columns_subset_D (S : CyclicStaircase) {g : Point3}
    (hg : MinimalComplement S.D g) (hf : FullSupport g) :
    thin23LiftedColumns S g ⊆ S.D

theorem t3_r3_h11_BW_height3 (S : CyclicStaircase) {g : Point3}
    (h12 : pair12Count S.D=3) (h13 : pair13Count S.D=3) (h23 : pair23Count S.D=3)
    (hx : g.x=3) (hy : g.y=1) (hz : g.z=1) : fullSupportSymbolicBW S g=27

theorem t3_unit_z_weight_relation (S : CyclicStaircase) {g : Point3}
    (hg : MinimalComplement S.D g) (hf : FullSupport g)
    (hx : g.x=2) (hy : g.y=2) (hz : g.z=1) : S.p3 = -2*S.p1-2*S.p2

theorem fullSupport_t3_ordered_symbolic_sharp (S : CyclicStaircase) {g : Point3}
    (hg : MinimalComplement S.D g) (hf : FullSupport g) (ho : PairCountsOrdered S)
    (ht : pair23Count S.D=3) : fullTarget S ≤ S.m
